mapper.select:
SELECT i.id, i.title, i.price, i.original_price, i.condition_level, i.status, , i.campus_id, c.name AS campus_name, i.category_id, cat.name AS category_name, i.favorite_count, i.view_count, i.published_at FROM items i JOIN campuses c ON c.id = i.campus_id JOIN categories cat ON cat.id = i.category_id WHERE i.status = 'ON_SALE'
AND i.title LIKE #{keyword} ESCAPE '!'
AND i.category_id IN
#{categoryId}
AND i.condition_level = #{condition}
AND i.price >= #{minPrice}
AND i.price <= #{maxPrice}
ORDER BY i.price ASC, i.id DESC
ORDER BY i.price DESC, i.id DESC
ORDER BY i.favorite_count DESC, i.view_count DESC, i.published_at DESC, i.id DESC
ORDER BY i.published_at DESC, i.id DESC

SELECT i.id, i.title, i.price, i.status, , i.admin_lock, i.off_shelf_reason, i.favorite_count, i.view_count, i.published_at, i.created_at, i.updated_at, i.version FROM items i WHERE i.seller_id = #{sellerId}
AND i.status = #{status}
ORDER BY i.created_at DESC, i.id DESC
